<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue'
import {useAuthStore} from '@/stores/auth'
import {useAdminUsersStore} from '@/stores/admin-users'
import type {AdminUser} from '@/api/admin-users'
import AdminUserAudit from '@/components/admin-users/AdminUserAudit.vue'
import AdminUserStatusDialog from '@/components/admin-users/AdminUserStatusDialog.vue'
import AdminUserDetail from '@/components/admin-users/AdminUserDetail.vue'
import '@/styles/admin-users.css'
const auth=useAuthStore(),store=useAdminUsersStore(),detailOpen=ref(false),statusOpen=ref(false),target=ref<AdminUser|null>(null),notice=ref(''),auditOpen=ref(false),auditId=ref<string>()
watch(()=>auth.user?.id,key=>{store.bindIdentity(key??'guest');detailOpen.value=false;statusOpen.value=false;target.value=null;notice.value='';auditOpen.value=false;auditId.value=undefined;if(auth.isAdmin)void store.load()},{immediate:true})
onBeforeUnmount(()=>{store.closeDetail();store.bindIdentity('')})
function search(){store.page=1;void store.load()}
function clear(){store.keyword='';store.role=store.status='ALL';search()}
function audit(id?:string){detailOpen.value=false;store.closeDetail();auditId.value=id;auditOpen.value=true}
function change(user:AdminUser){detailOpen.value=false;store.closeDetail();target.value=user;statusOpen.value=true}
async function saved(){statusOpen.value=false;target.value=null;notice.value='账号状态已更新。';await store.load()}
async function reloadTarget(){if(!target.value)return;await store.detail(target.value.id);if(store.selected){target.value=store.selected;store.commandConflict=false}else store.commandError=store.detailError}
function detail(id:string){detailOpen.value=true;void store.detail(id)}
</script>
<template><section class="users-page"><header class="users-heading"><div><h1>用户管理</h1><p>查看账号资料，管理启用状态与操作记录。</p></div><button @click="audit()">操作记录</button></header><p v-if="notice" role="status" class="users-help">{{notice}}</p><form class="users-filters" @submit.prevent="search"><input v-model="store.keyword" aria-label="搜索账号、昵称或ID" placeholder="搜索账号、昵称或 ID"><label>状态<select v-model="store.status"><option value="ALL">全部状态</option><option value="ENABLED">正常</option><option value="DISABLED">已停用</option></select></label><label>角色<select v-model="store.role"><option value="ALL">全部角色</option><option value="USER">学习者</option><option value="ADMIN">管理员</option></select></label><button class="button-primary" :disabled="store.loading">搜索</button><button type="button" :disabled="store.loading" @click="clear">清空筛选</button></form><p v-if="store.error" role="alert" class="users-error">{{store.error}} <button @click="store.load()">重试</button></p><div class="users-summary"><span>匹配 {{store.total}} 个账号</span><span v-if="store.loading" role="status">正在加载账号…</span><span>账号资料 · 管理员可见</span></div><div class="users-list"><div class="users-row users-table-head"><span>账号 / 昵称</span><span>角色</span><span>状态</span><span class="users-date">注册时间</span><span>操作</span></div><article v-for="user in store.rows" :key="user.id" class="users-row" :data-user-id="user.id"><div class="users-account"><strong>{{user.username}}</strong><small>{{user.displayName}} · ID {{user.id}}</small></div><div class="users-role"><span class="users-badge">{{user.roles.includes('ADMIN')?'管理员':'学习者'}}</span></div><div class="users-state"><span class="users-badge" :class="user.enabled?'ok':'off'">{{user.enabled?'正常':'已停用'}}</span></div><span class="users-date">{{new Date(user.createdAt).toLocaleDateString('zh-CN')}}</span><div class="users-row-actions"><button @click="detail(user.id)">详情</button><button :disabled="user.protectedAccount" :class="{'users-danger':user.enabled}" @click="change(user)">{{user.protectedAccount?'受保护':user.enabled?'停用':'恢复'}}</button></div></article><p v-if="!store.loading&&!store.rows.length" class="users-empty">没有找到匹配的账号，试试其他条件。</p></div><div class="users-pager"><span>停用保留学习与留言记录，不删除内容。</span><div><button :disabled="store.loading||store.page<=1" @click="store.page--;store.load()">上一页</button><span>{{store.page}} / {{Math.max(1,Math.ceil(store.total/20))}}</span><button :disabled="store.loading||store.page*20>=store.total" @click="store.page++;store.load()">下一页</button></div></div><p class="users-footnote">密码采用不可逆哈希保存。管理端不显示密码或哈希。</p><AdminUserDetail :open="detailOpen" :user="store.selected" :loading="store.detailLoading" :error="store.detailError" @close="detailOpen=false;store.closeDetail()" @status="change" @audit="audit" /><AdminUserStatusDialog :open="statusOpen" :target="target" @close="statusOpen=false" @saved="saved" @reload="reloadTarget" /><AdminUserAudit :open="auditOpen" :user-id="auditId" @close="auditOpen=false" /></section></template>
